import { useId, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Card } from "@registry/aikoz/card/card";
import { CountBadge, type CountBadgeTone } from "@registry/aikoz/count-badge/count-badge";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface KanbanColumn {
  key: string;
  /** Titre de la colonne. Il NOMME la section : `aria-labelledby` pointe dessus. */
  title: string;
  /** Ce que la colonne contient, et ce qu'on attend de l'utilisateur. */
  subtitle: string;
  /**
   * Pilote le liseré ET le compteur — une seule décision, pas deux.
   *
   * Le ton dit l'urgence, jamais autre chose : `info` ce qui attend,
   * `warning` ce qui cloche, `error` ce qui presse. Une colonne dont le ton
   * ne dit rien prend `primary`.
   */
  tone: CountBadgeTone;
  /**
   * Compte affiché. Séparé du contenu **volontairement** : une colonne peut
   * n'en rendre qu'une partie (« Voir plus »), et c'est le total qui compte.
   */
  count: number;
  /** Le corps de la colonne. Le tableau décide de ses cartes. */
  children: ReactNode;
}

export interface KanbanBoardProps {
  columns: KanbanColumn[];
  className?: string;
}

/** Le liseré reprend la couleur du ton : une décision, pas deux. */
const LISERE: Record<CountBadgeTone, string> = {
  primary: "--primary",
  info: "--info",
  warning: "--warning",
  error: "--destructive-text",
};

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Tableau à colonnes.
 *
 * **Ce qu'il fait, et que rien d'autre ne fait** : il tient le contrat de
 * structure d'un tableau à colonnes, quel que soit ce qu'on y met.
 *
 * - chaque colonne est une `section` NOMMÉE par son titre (`aria-labelledby`),
 *   donc atteignable au repère par un lecteur d'écran ;
 * - le compte est un `CountBadge` étiqueté, jamais un nombre nu ;
 * - le liseré et le compteur partagent la couleur du ton, sans qu'on puisse
 *   les désaccorder ;
 * - une colonne par ligne sous `md`, où trois colonnes côte à côte ne se
 *   lisent plus.
 *
 * **Il ne décide de rien d'autre.** Les cartes sont fournies par l'appelant :
 * une file de réponses et un circuit de validation n'affichent pas les mêmes
 * choses, et le jour où ils divergeraient dans un composant unique, c'est ce
 * composant qui deviendrait illisible.
 *
 * `ResponseKanban` est bâti dessus — c'est le même tableau, avec trois
 * colonnes qu'il connaît.
 *
 * ## Le gabarit d'en-tête n'est pas un composant
 *
 * Liseré + titre + sous-titre + compteur est reproduit ici en JSX. Louis a
 * tranché le 10/09/2026 que « En-tête de section » est un GABARIT de mise en
 * page et non un composant de bibliothèque ; on suit cette décision.
 */
export function KanbanBoard({ columns, className }: KanbanBoardProps) {
  const uid = useId();

  return (
    <div
      className={cn(
        "grid grid-cols-1 items-start gap-4",
        // Le nombre de colonnes suit la donnée, sans classe conditionnelle
        // à écrire : `md:grid-cols-2` et `md:grid-cols-3` ne se génèrent pas
        // dynamiquement en Tailwind, mais une variable CSS, si.
        "md:[grid-template-columns:repeat(var(--kanban-colonnes),minmax(0,1fr))]",
        className,
      )}
      style={{ "--kanban-colonnes": columns.length } as React.CSSProperties}
    >
      {columns.map((c) => {
        const titreId = `${uid}-${c.key}`;
        return (
          <Card
            key={c.key}
            as="section"
            aria-labelledby={titreId}
            surface="flat"
            density="compact"
            className="gap-4"
          >
            <div className="flex items-start justify-between gap-2">
              <div
                className="flex min-w-0 flex-col gap-0.5 border-l-4 pl-3"
                style={{ borderColor: `var(${LISERE[c.tone]})` }}
              >
                <h3 id={titreId} className="m-0 text-sm font-semibold text-foreground">
                  {c.title}
                </h3>
                <p className="m-0 text-xs text-muted-foreground">{c.subtitle}</p>
              </div>
              <CountBadge
                value={c.count}
                variant="count"
                tone={c.tone}
                label={`éléments dans « ${c.title} »`}
              />
            </div>
            {c.children}
          </Card>
        );
      })}
    </div>
  );
}

import { forwardRef, type ElementType, type HTMLAttributes } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

// `min-w-0` n'est pas une précaution, c'est ce qui fait tenir la promesse de
// `overflow-x-auto` des composants qu'on met DEDANS.
//
// Un élément de grille ou de flex vaut `min-width: auto` par défaut : il ne
// rétrécit jamais sous la largeur de son contenu. Mesuré sur le tableau de
// bord à 390 px de large : la grille faisait 350, la carte 406, et le
// tableau qu'elle contenait débordait donc la PAGE de 36 px — alors qu'il
// avait bien son propre conteneur scrollable. Le scroll interne ne peut pas
// contenir ce que son parent laisse s'élargir.
const cardVariants = cva("flex flex-col min-w-0", {
  variants: {
    surface: {
      /**
       * Carte standard. La bordure porte la STRUCTURE ; l'élévation vient du
       * REGISTRE et n'ajoute que la PROFONDEUR — aucune en produit, deux
       * couches transparentes en marketing.
       *
       * `better-ui` recommande de remplacer la bordure par un anneau d'ombre.
       * On s'en écarte, et c'est mesuré : cet anneau donne 1,18:1 contre la
       * page en clair et 1,00 en sombre, moins que la bordure qu'il
       * remplacerait. La carte disparaîtrait.
       */
      raised: [
        "text-card-foreground",
        // La surface n'est plus un APLAT. Un dégradé très court, de `--card`
        // vers 30 % du fond de page, suffit à donner à la carte un haut et un
        // bas — c'est ce qui sépare les tableaux de bord récents de ceux qui
        // font vieux, et c'est le seul geste de la référence QORE qui tienne
        // en produit sans devenir décoratif.
        //
        // Le sens est imposé par le thème et non choisi : le mélange va vers
        // la PAGE, donc en clair le bas se grise à peine et en sombre il
        // s'assombrit. Un dégradé écrit en dur aurait éclairci le haut, ce qui
        // est impossible en clair où la carte est déjà blanche.
        "[background:linear-gradient(180deg,var(--card)_0%,color-mix(in_oklch,var(--card),var(--background)_30%)_100%)]",
        // Propriété arbitraire `[box-shadow:…]`, et NON l'utilitaire
        // `shadow-…`. Deux échecs successifs l'ont imposé : `shadow-[var(…)]`
        // fait prendre à Tailwind un `var()` nu pour une COULEUR d'ombre — il
        // émet `--tw-shadow-color` et rien ne se voit ; et même avec l'indice
        // de type, son système de composition (`--tw-shadow`,
        // `--tw-ring-shadow`, `--tw-shadow-colored`) écrase les couleurs d'une
        // ombre multi-couches. La propriété arbitraire court-circuite tout ça.
        "border border-border rounded-[var(--radius)]",
        "[box-shadow:var(--role-elevation-card)]",
        "transition-[box-shadow] duration-150 ease-out",
        "hover:[box-shadow:var(--role-elevation-card-hover)]",
      ].join(" "),
      /** Bordure franche, aucune élévation — pour une grille dense. */
      flat: "bg-card text-card-foreground border border-border rounded-[var(--radius)]",
      /** Ni bord ni ombre : un simple regroupement, quand le conteneur cadre déjà. */
      bare: "bg-card text-card-foreground rounded-[var(--radius)]",
      /**
       * LA carte qui prime — une seule par écran.
       *
       * Dans une grille où toutes les cartes se ressemblent, aucune ne prime.
       * Celle-ci prime sans ajouter de couleur au système ni changer sa
       * taille. C'est le geste des tableaux de bord bancaires — une carte
       * noire pour le solde, des cartes blanches pour le reste.
       *
       * **Le rôle est la hiérarchie, pas l'inversion.** La variante s'est
       * longtemps appelée `inverse`, du nom de son MOYEN : retourner le
       * thème. Le moyen ne marchait qu'en clair. Mesuré sur le tableau de
       * bord, la carte valait 0,05 fois la clarté des autres en thème clair —
       * elle s'enfonce, c'est reposant — et **15,3 fois** en thème sombre :
       * 120 000 px² de pleine clarté sur une page à 0,001 de luminance, le
       * seul point de l'écran qui éblouisse un œil adapté au noir. Le
       * contraste était symétrique, le confort ne l'était pas.
       *
       * En sombre elle est donc devenue un **panneau allumé** plutôt qu'un
       * aplat blanc : 2,5 fois la clarté d'une carte, un saut de clarté OKLCH
       * de 0,223 à 0,470. OKLCH étant perceptuellement uniforme, ce saut se
       * voit bien plus que le rapport ne le laisse croire.
       *
       * D'où la règle d'emploi : **une seule par écran**. Deux cartes
       * héroïnes ne hiérarchisent plus rien, elles font un damier.
       *
       * Le dégradé se lit en deux couches. La base va d'un palier de la rampe
       * de chrome à un autre — même rampe, donc la surface reste une surface :
       * un dégradé qui change de teinte se lit comme une image. Par-dessus,
       * une lueur d'angle porte la SECONDE couleur de marque, qui suit
       * `data-brand` : marine vers campanule chez ADP, encre vers vert chez
       * Extime. C'est là que la marque se voit vraiment.
       */
      heros: [
        "rounded-[var(--radius)] border border-transparent",
        "text-[var(--on-hero)]",
        "[background:radial-gradient(130%_150%_at_88%_0%,color-mix(in_oklch,var(--hero-glow),transparent_58%)_0%,transparent_62%),linear-gradient(135deg,var(--surface-hero)_0%,var(--surface-hero-to)_100%)]",
        "[box-shadow:var(--role-elevation-card)]",
        "transition-[box-shadow] duration-150 ease-out",
        "hover:[box-shadow:var(--role-elevation-card-hover)]",
      ].join(" "),
      /**
       * ANCIEN NOM de `heros`, rendu à l'identique.
       *
       * Louis consomme le registry PUBLIÉ : retirer une valeur de variante
       * casserait son application au prochain `shadcn add`. Elle reste donc,
       * et pointe sur le même rendu. À ne plus employer — le nom décrivait
       * le moyen, pas le rôle.
       */
      inverse: [
        "rounded-[var(--radius)] border border-transparent",
        "text-[var(--on-hero)]",
        "[background:radial-gradient(130%_150%_at_88%_0%,color-mix(in_oklch,var(--hero-glow),transparent_58%)_0%,transparent_62%),linear-gradient(135deg,var(--surface-hero)_0%,var(--surface-hero-to)_100%)]",
        "[box-shadow:var(--role-elevation-card)]",
        "transition-[box-shadow] duration-150 ease-out",
        "hover:[box-shadow:var(--role-elevation-card-hover)]",
      ].join(" "),
    },
    density: {
      compact: "p-4 gap-2",
      default: "p-5 gap-3",
      large: "p-6 gap-4",
    },
  },
  defaultVariants: { surface: "raised", density: "default" },
});

export interface CardProps
  extends HTMLAttributes<HTMLElement>,
    VariantProps<typeof cardVariants> {
  /**
   * Élément rendu. `div` par défaut — mais une carte qui présente un contenu
   * autonome (un avis, un article) doit sortir en `article`, et une carte qui
   * regroupe une section nommée en `section`. Le choix est sémantique, pas
   * décoratif : il change les repères de navigation d'un lecteur d'écran.
   */
  as?: "div" | "article" | "section" | "li";
}

/**
 * Conteneur de carte.
 *
 * Volontairement sans sous-composants `Header` / `Title` / `Footer` : le
 * niveau de titre dépend du plan de la page, pas de la carte. Un `CardTitle`
 * qui figerait un `h3` casserait la hiérarchie dès qu'une carte est utilisée
 * ailleurs. C'est à l'appelant de poser le bon niveau.
 */
export const Card = forwardRef<HTMLElement, CardProps>(function Card(
  { as = "div", surface, density, className, ...props },
  ref
) {
  // `as` est polymorphe : les types d'événements diffèrent d'un élément à
  // l'autre (un HTMLLIElement n'est pas un HTMLDivElement). On type le
  // composant sur HTMLElement et on élargit ici, plutôt que d'imposer à
  // l'appelant des handlers spécifiques au div.
  const Tag = as as ElementType;
  return (
    <Tag
      ref={ref as never}
      className={cn(cardVariants({ surface, density }), className)}
      {...props}
    />
  );
});

export { cardVariants };

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const countBadgeVariants = cva(
  [
    "inline-flex items-center justify-center shrink-0",
    // `min-w` + `px` plutôt qu'une largeur fixe : un "9" reste un cercle, un
    // "12" ou "99" élargit la pastille en pilule au lieu de se faire couper —
    // même mécanique que le compteur de `NavItem`.
    "min-w-5 h-5 px-1 text-2xs font-semibold tabular-nums leading-none",
  ],
  {
    variants: {
      variant: {
        // Cercle plein — attire l'œil, pour un compte à traiter (colonne
        // Kanban). La couleur du remplissage est fixée par `tone`.
        count: ["rounded-full"],
        // Marqueur discret — un rang dans une liste, pas une alerte. Contour
        // fin plutôt qu'aplat, poids visuel volontairement plus bas ; carré
        // (coins arrondis) et non cercle, pour qu'on ne confonde jamais les
        // deux variantes au premier coup d'œil. Reprend l'état "à venir" du
        // `Stepper` : `--border-strong` / `--muted-foreground`. `tone` est
        // ignoré ici — un marqueur de rang reste sobre dans tous les cas.
        rank: [
          "rounded-[var(--radius)] border border-[var(--border-strong)]",
          "bg-transparent text-muted-foreground",
        ],
      },
      // N'affecte que `variant="count"` (cf. `compoundVariants`) — mesuré,
      // pas choisi à l'œil.
      //
      // `info` et `warning` passent du PLEIN au VOILÉ, et ce n'est pas une
      // question de goût. Ils posaient du blanc sur `--info` / `--warning`,
      // qui sont les rôles TEXTE. Ça tenait tant que ces rôles restaient
      // sombres en thème sombre ; relevés au seuil perceptuel ils
      // s'éclaircissent, et du blanc dessus ne tient plus.
      //
      // Un aplat dédié a été essayé puis retiré : mesuré, `status.warning`
      // ne marche avec AUCUN texte dans les deux thèmes (blanc 2,18:1 en
      // clair, encre 45 en APCA sombre pour `info`). Un jaune vif est un
      // mauvais fond de pastille, point.
      //
      // Le voile, lui, tient partout : `--warning` sur `--warning-subtle`
      // vaut APCA 83 en clair comme en sombre, `--info` 75 et 83. Et il
      // range la hiérarchie — `primary` et `error` restent pleins, ce qui
      // les distingue enfin d'un simple compteur d'information.
      tone: {
        primary: "",
        info: "",
        warning: "",
        error: "",
      },
    },
    compoundVariants: [
      { variant: "count", tone: "primary", class: "bg-[var(--primary)] text-[var(--primary-foreground)]" },
      { variant: "count", tone: "info", class: "bg-[var(--info-subtle)] text-[var(--info)]" },
      { variant: "count", tone: "warning", class: "bg-[var(--warning-subtle)] text-[var(--warning)]" },
      { variant: "count", tone: "error", class: "bg-[var(--destructive)] text-[var(--destructive-foreground)]" },
    ],
    defaultVariants: { variant: "count", tone: "primary" },
  }
);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface CountBadgeProps extends VariantProps<typeof countBadgeVariants> {
  /** Chiffre ou nombre court affiché, centré (1 à 2 caractères visés). */
  value: number | string;
  className?: string;
  /**
   * Précision lue par les lecteurs d'écran, **en plus** du contenu visible.
   * Même convention que `label` sur `Badge` : utile quand la pastille se
   * retrouve isolée (sans le titre de colonne ou la ligne de liste qui,
   * normalement, porte déjà le sens) — ex. `label="en attente"` pour que "7"
   * s'annonce "7 en attente" plutôt que "7" tout court.
   *
   * `null` quand un parent annonce déjà le nombre ET son sens (cas courant :
   * un en-tête de colonne qui dit "7 avis en attente", une ligne de liste qui
   * énonce son propre rang) — la pastille devient alors purement décorative,
   * comme le fait déjà la pastille inline de `NavItem`.
   */
  label?: string | null;
}

export type CountBadgeTone = "primary" | "info" | "warning" | "error";

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Badge / pastille numérique — affiche un nombre court dans un repère visuel
 * compact : compte d'éléments en attente (`count`, cercle plein) ou indicateur
 * de rang (`rank`, marqueur discret). Cousin générique de la pastille inline
 * de `NavItem` (même idée de cercle rempli avec un chiffre), mais construit
 * sur les tokens `--primary` / `--border-strong` plutôt que sur les tokens de
 * navigation — utilisable partout : en-tête de colonne Kanban, liste numérotée.
 *
 * Purement informatif : ni cliquable, ni focusable, un seul état.
 *
 * Ne porte jamais seul l'information : `value` est toujours accompagné, dans
 * son contexte d'usage, d'un texte qui dit ce qui est compté ou classé — la
 * pastille n'a donc pas à dupliquer ce sens elle-même. Voir `label` pour le
 * cas où elle se retrouve isolée.
 */
export function CountBadge({
  value,
  variant = "count",
  tone = "primary",
  label,
  className,
}: CountBadgeProps) {
  const decorative = label === null;
  return (
    <span
      className={cn(countBadgeVariants({ variant, tone }), className)}
      aria-hidden={decorative ? true : undefined}
    >
      {value}
      {!decorative && label && <span className="sr-only"> {label}</span>}
    </span>
  );
}

export { countBadgeVariants };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
